"""Deliberately tangled, low-maintainability module."""

def process_1(data):
    total = 0
    for item in data:
        if item > 0:
            if item % 2 == 0:
                if item > 10:
                    total += item * 2
                else:
                    total += item
            else:
                if item > 5:
                    total += item - 1
                else:
                    total -= item
        elif item < 0:
            total -= abs(item)
        else:
            total += 1
    return total

